  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 11, 6, 9, 8, 4, '{"compensation": "Only an ''up to 15%'' ceiling is published on the brand''s page; no flat rate could be recorded.", "contact_access": "Join route is published on the brand''s own affiliate page; no public partnerships email was found.", "credibility": "The Awin route is verified from the brand''s own page; rate detail is thin.", "niche_fit": "Mineral sunscreen fits skincare UGC, though the single-category range is narrower than full skincare lines.", "opportunity_availability": "Open joining via Awin, with US tax documentation required on approval.", "ugc_evidence": "The brand maintains its own affiliate page linked to Awin, but publishes no creator-specific program details."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Vivaia', 'https://www.vivaia.com/', 'Sustainable women''s footwear brand making washable flats, heels and sneakers from recycled materials with 3D-knit construction. Its affiliate program runs on Impact (also listed via ShareASale) and pays a 10% base commission with performance tiers up to 20%, a 30-day cookie, and a published affiliate contact email (affiliate@vivaia.com).', null, 'published') returning id into bid;
