  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkclicky.com/affiliate-program/vivaia/.', 'https://linkclicky.com/affiliate-program/vivaia/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Vivaia Affiliate Program (Impact)', 'https://linkclicky.com/affiliate-program/vivaia/', 'https://linkclicky.com/affiliate-program/vivaia/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/vivaia/', 'affiliate_directory', 'commission_rate', 'The LinkClicky affiliate directory profile for VIVAIA (dated March 11, 2024) lists the program on the Impact platform, open to all regions, paying 10% per sale. No earnings-cap statement appears in the profile, so the cap is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://theaffiliatemonkey.com/affiliate/vivaia-int-affiliate-program/', 'affiliate_directory', 'creator_program', 'The Affiliate Monkey''s fetched VIVAIA program page states in its FAQ: ''Affiliates earn a base commission of 10%, with the potential to earn up to 20% per sale depending on performance'', gives a 30-day cookie, says creators can join ''through networks like ShareASale or Impact'', and publishes the contact ''reach out to affiliate@vivaia.com''. The 10% base is recorded; the up-to-20% figure is a performance ceiling, not the base rate, and no cap statement is published.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 15, 12, 8, 4, '{"niche_fit": "Washable, travel-friendly flats and sneakers are a proven fashion-UGC staple - styling, comfort-test and pack-with-me content.", "ugc_evidence": "The program explicitly recruits influencers, bloggers and content creators and supplies creatives and promotional codes, per the fetched program pages.", "compensation": "10% base with published performance tiers to 20% and a 30-day cookie is above standard footwear rates; figures are directory-reported, not brand-page-verified.", "contact_access": "A public affiliate email (affiliate@vivaia.com) is published, plus join routes on Impact and ShareASale.", "opportunity_availability": "Open network program, all regions per the directory profile; approval may take several days.", "credibility": "Established global footwear brand; program terms rest on two independent directory listings that agree on the 10% base."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Metta Voyage', 'https://mettavoyage.com', 'Hanoi-based licensed international tour operator running private, tailor-made 4-5 star journeys across Vietnam, Cambodia, Laos, Thailand and Bali. Its own Ambassadors page recruits travel bloggers and creators with a 4-8% commission on confirmed trip prices (tiered by monthly sales), 90-day tracking, monthly payouts from $300, and an FAQ stating there is no cap on earnings.', 'Vietnam', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 4, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://mettavoyage.com/affiliates-program/.', 'https://mettavoyage.com/affiliates-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Metta Voyage Ambassadors (Brand direct)', 'https://mettavoyage.com/affiliates-program/', 'https://mettavoyage.com/affiliates-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mettavoyage.com/affiliates-program/', 'official_program_page', 'commission_rate', 'The brand''s own Ambassadors page: ''You earn 4-8% of every confirmed trip price, based on your confirmed sales in the month: 4% under $15,000, 6% from $15,000 to $49,999, 8% from $50,000'', excluding international flights, taxes, insurance and card fees, with 90-day tracking and monthly payment by bank transfer, PayPal or Wise once approved commissions reach $300. The 4% tier floor is recorded as the base rate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mettavoyage.com/affiliates-program/', 'official_program_page', 'creator_program', 'The same page is creator-first - ''Travel bloggers & creators: Blogs, Instagram, YouTube, TikTok and newsletters'' - with no minimum audience, approval within 2 business days, personal links and QR codes, a real-time dashboard and a marketing kit. Its ''How much can I earn?'' FAQ repeats the 4-8% structure and states: ''There is no cap: every confirmed trip you refer counts.'' The earnings question is answered with an explicit no-cap statement, so commission_cap is UNCAPPED. No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 13, 9, 8, 4, '{"niche_fit": "Private Asia itineraries are high-value travel-creator content; one referred trip is worth $120-$240 at entry tier.", "ugc_evidence": "The brand''s own page names travel bloggers and creators across Instagram, YouTube and TikTok, and supplies ready-to-use photos and copy.", "compensation": "4% base sounds low but applies to multi-thousand-dollar trips ($120 on a $3,000 trip), rising to 8%; verified uncapped on the brand''s own FAQ.", "contact_access": "A dedicated contact in the Hanoi team is promised in the dashboard, but no public affiliate email is published on the page (site emails are obfuscated).", "opportunity_availability": "Free to join, no minimum audience, approval within 2 business days; $300 payout threshold is a friction point.", "credibility": "Licensed international tour operator (licence 01-1167/2023/CDLQGVN-GP LHQT), 4.9 on Tripadvisor with 2,000+ bookings and 10,100+ travellers stated on the page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Leatherology', 'https://www.leatherology.com', 'Personalizable full-grain leather goods brand - monogrammed wallets, bags, passport covers and travel sets aimed at gifting. Its own affiliate page for creators and bloggers runs through Rakuten Advertising and LTK, promises a dedicated Affiliate Manager, product samples and creative assets, and states twice that there is no cap on earnings; the commission rate itself is only shown inside the network dashboard after approval.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Rakuten Advertising', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.leatherology.com/pages/affiliates/.', 'https://www.leatherology.com/pages/affiliates/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Leatherology Affiliate Program (Rakuten Advertising / LTK)', 'https://www.leatherology.com/pages/affiliates/', 'https://www.leatherology.com/pages/affiliates/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.leatherology.com/pages/affiliates/', 'official_program_page', 'commission_rate', 'The brand''s own affiliate page: ''Earn commission on every qualifying order you refer, with no cap on your earnings'' and ''You''ll earn commission on the subtotal of every qualifying order placed through your link, and there''s no cap on what you can make.'' The fetched page explicitly states there is no earnings cap, so commission_cap is UNCAPPED. The page also states the rate is NOT published publicly: ''Your current rate and the full program terms are shown in your Rakuten or LTK dashboard once you''re approved'' - so commission_rate is recorded as null rather than guessed.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.leatherology.com/pages/affiliates/', 'official_program_page', 'creator_program', 'The same page (''Affiliate Program for Creators & Bloggers'', ''Calling All Influencers'') recruits gift and lifestyle bloggers, wedding creators, everyday-carry channels and travel creators, is free to join with no minimum sales quota or exclusivity, offers product samples and a named Affiliate Manager after approval, and runs through Rakuten (long-form) and LTK (social). It points to an LTK brand profile showing ''nearly 2,000 creators'' - a four-figure count is not low, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 17, 10, 9, 9, 4, '{"niche_fit": "Monogrammed leather gifts are evergreen gift-guide, wedding and everyday-carry content with year-round gifting moments.", "ugc_evidence": "Creator-first own page naming bloggers, YouTube channels and shoppable social, with samples, creative assets and launch previews.", "compensation": "Verified uncapped, but the rate is dashboard-only after approval, so compensation cannot be graded higher until a rate is visible.", "contact_access": "A dedicated Affiliate Manager is introduced after approval; no public partnerships email is published on the page.", "opportunity_availability": "Free to join, no quota, no exclusivity, two network routes (Rakuten and LTK).", "credibility": "Established personalization brand with a detailed, transparent program page; the LTK profile it cites shows nearly 2,000 creators already sharing its pieces."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Smart Birdy', 'https://www.smartbirdy.com', 'Premium women''s luggage brand (Birdy Boutique) selling stackable leather carry-ons and travel accessories priced $250-$1,000. Its own affiliate page, run on ShareASale, offers content creators, bloggers and influencers a 15% commission on each sale, a 60-day tracking window, monthly payouts and ready-to-use marketing assets through its Jetsetter Club community.', null, 'published') returning id into bid;
