  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Smart Birdy Affiliate Program (ShareASale)', 'https://www.smartbirdy.com/pages/smart-birdy-affiliate', 'https://www.smartbirdy.com/pages/smart-birdy-affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.smartbirdy.com/pages/smart-birdy-affiliate', 'official_program_page', 'commission_rate', 'The brand''s own affiliate page: ''Generous Commission: Earn a 15% commission on each sale'', ''Extended Tracking Period: Enjoy a 60-day tracking window'', monthly payouts, and a ShareASale join link (shareasale.com/join/smartbirdy) on the same page. No earnings-cap statement appears, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.smartbirdy.com/pages/smart-birdy-affiliate', 'official_program_page', 'creator_program', 'The same page states the program ''is open to content creators, bloggers, social media influencers, and anyone who loves sharing travel tips'', offers banners, links and promotional materials plus an affiliate team for support, and frames membership as the ''Birdy Jetsetters'' community. No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 15, 15, 8, 8, 3, '{"niche_fit": "Luxury women''s luggage is a focused but real travel-fashion niche - packing, carry-on and airport-style content.", "ugc_evidence": "Own page explicitly recruits creators and influencers and provides ready-to-use marketing assets and a creator community.", "compensation": "15% on $250-$1,000 products with a 60-day window is strong for luggage; rate is brand-published.", "contact_access": "Apply via the ShareASale link on the brand page; no public affiliate email is published.", "opportunity_availability": "Open application on the brand page; approval step applies.", "credibility": "Small premium brand (Birdy Boutique) with a complete, transparent program page; no independent scale signals were verified."}'::jsonb);
