  insert into public.brands (name, website, description, country, status) values ('Composite Athlete', 'https://compositeathlete.com', 'Training-plan brand selling printable workbooks with app-delivered programs for everyday athletes (first half marathon, starting to lift, 5K to 10K). Its own partner page for athletes and creators pays 40% of workbook and store-program sales and 30% of Athlete Pro subscription payments for the first 12 months, with 60-day link credit and free access to every plan for approved partners.', null, 'published') returning id into bid;
