  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Composite Athlete Partner Program (Brand direct)', 'https://compositeathlete.com/partners', 'https://compositeathlete.com/partners', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://compositeathlete.com/partners', 'official_program_page', 'commission_rate', 'The brand''s own partner page: ''Recommend the plan that fits, and earn 40% of every sale you send us'', with a rate table - printable workbook or book with app program $9.99-$14.99 at 40%, store programs $19-$59 at 40%, Athlete Pro monthly/annual at 30% of payments for the first 12 paid months (Lead Partner tier at 25+ paid sales in 30 days pays 50%/40%). Commission is on collected revenue after refunds, link credit lasts 60 days, commissions pend 30 days then pay monthly at a $25 balance. The headline 40% product rate is recorded. No earnings-cap statement appears, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://compositeathlete.com/partners', 'official_program_page', 'creator_program', 'The same page is addressed to ''Athletes and creators'' whose followers ask what plan they follow: partners choose a link name, get a ?via= link and a 10%-off code for their audience, receive free access to every plan, and ''we reply to every application by email''. No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 21, 14, 17, 9, 8, 3, '{"niche_fit": "Goal-based plans (first half marathon, first lifting program) map directly onto fitness-creator series content.", "ugc_evidence": "Own page built for athletes and creators, with a personal link name, audience discount code and free access to every plan to film with.", "compensation": "40% of product sales (30% on subscriptions for 12 months) is a top-tier digital-fitness rate, brand-published with full terms.", "contact_access": "Apply on the brand''s own page; every application gets an email reply, but no public email is published.", "opportunity_availability": "Open application on the brand page; approval step applies.", "credibility": "Small, newer plan brand; terms are transparent and complete, but scale is unproven."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Freeletics', 'https://www.freeletics.com', 'Europe''s large AI-coached fitness app - personalised HIIT and strength training plans built by its AI Coach, with 57 million users claimed on its network profile. Its Brand Partnerships programme runs on Awin (UK profile fetched); the public profile does not publish a commission rate, so the rate is recorded as null.', null, 'published') returning id into bid;
