  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/72497.', 'https://ui.awin.com/merchant-profile/72497', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Freeletics Brand Partnerships (Awin)', 'https://ui.awin.com/merchant-profile/72497', 'https://ui.awin.com/merchant-profile/72497', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/72497', 'affiliate_network', 'affiliate_program', 'Freeletics'' Awin merchant profile (fetched, ''Freeletics Brand Partnerships UK Affiliate Programme'', merchant ID 72497) confirms the brand runs an affiliate programme on Awin and describes the app: ''Freeletics, Europe''s #1 fitness app... The heart of the app is the AI-powered Coach'', with ''data-based insights from over 57 million users''. The public profile text does not publish a commission rate or any earnings-cap statement, so the rate is recorded as null and the cap as unknown rather than guessed.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 13, 6, 9, 8, 5, '{"niche_fit": "AI-coached home workouts are a core fitness-creator topic - transformations, no-equipment routines and app reviews.", "ugc_evidence": "Verified Awin programme from a mass-market fitness app; no creator-specific program page was verified.", "compensation": "Rate is not published on the public network profile, so compensation scores low until confirmed inside Awin.", "contact_access": "Join route is the public Awin merchant profile; no public partnerships email was verified.", "opportunity_availability": "Open Awin programme confirmed on the network profile (UK programme fetched).", "credibility": "One of Europe''s largest fitness apps, with 57 million users claimed on its Awin profile; programme existence verified on Awin itself."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Ultra+', 'https://www.ultraplus.fit', 'Training app for lifters (AI coach ''Blaze'', workout and nutrition tracking) with a creator partner program on its own page: a flat $10 per yearly-plan conversion and $5 per monthly-plan conversion (one payment per conversion, not recurring), a 14-day hold, Stripe Connect payouts, a free Pro account for content, and manual review open to fitness creators of any size. Its ''no cap on how many'' wording covers conversion count only, so the earnings cap is honestly recorded as unknown.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.ultraplus.fit/affiliates.', 'https://www.ultraplus.fit/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Ultra+ Partner Program (Brand direct)', 'https://www.ultraplus.fit/affiliates', 'https://www.ultraplus.fit/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.ultraplus.fit/affiliates', 'official_program_page', 'commission_rate', 'The brand''s own partner page: ''One payment per conversion. No cap on how many. Yearly subscription $10 - one payment per conversion. Monthly subscription $5 - one payment per conversion'', ''Commissions clear 14 days after the purchase... Paid through Stripe Connect'', and its FAQ: ''Is the commission recurring? No. You earn one payment per conversion.'' This is a flat bounty, so commission_rate is null with the bounty recorded here. The ''no cap'' wording covers the NUMBER of conversions, not an earnings ceiling, so commission_cap stays unknown per the standing standard.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.ultraplus.fit/affiliates', 'official_program_page', 'creator_program', 'The same page is creator-first: partners get a free Ultra+ Pro account ''so you can show real workouts'', a personal discount code and trackable link, a partner dashboard and a private partner group; ''Do I need a large following? No... Fitness and strength creators of any size can apply'', with manual review of content quality and any platform accepted (Instagram, TikTok, YouTube, X, newsletters, podcasts). No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 16, 9, 9, 7, 3, '{"niche_fit": "A lifting-focused training app with screenshot-friendly tracking is natural strength-creator content.", "ugc_evidence": "Own page built for creators: free Pro account to film real workouts, personal code and link, partner group and early creative access.", "compensation": "Flat $10/$5 per conversion is modest and non-recurring, but terms are fully transparent and paid via Stripe Connect after 14 days.", "contact_access": "Direct application on the brand''s own page with human review and email replies; no public email is published.", "opportunity_availability": "Open to creators of any size, but every application is manually reviewed for content fit.", "credibility": "Small, newer app brand; program terms are unusually transparent, but scale and longevity are unproven."}'::jsonb);
