  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Elix Herbal Ambassador Program', 'https://elixhealing.aspireiq.com/join/herbalambassador', 'https://elixhealing.aspireiq.com/join/herbalambassador', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://elixhealing.aspireiq.com/join/herbalambassador', 'brand_website', 'affiliate_program', 'Elix''s own ambassador page (hosted on its AspireIQ portal), fetched first-hand, states ambassadors earn 15% commission on every order placed through their unique link, with bonuses and paid partnership opportunities; applicants must be US or Canada residents aged 20+, the program accepts a limited number of applicants, and the page publishes the contact email ambassadors@elixhealing.com. Third-party figures conflict (Shopper lists up to 9.97%; LinkClicky lists 10% via Impact), so the brand''s own published 15% governs. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 13, 12, 7, 4, '{"compensation": "15% commission on every order is published on the brand''s own ambassador page; no cap statement, so the cap is unknown.", "contact_access": "A dedicated program email (ambassadors@elixhealing.com) is published on the application page itself.", "credibility": "An established DTC women''s wellness brand with a clinician-formulated, personalized product model.", "niche_fit": "Personalized herbal formulas for cycle and hormone health are routine-based, story-driven products that fit women''s wellness and hormone-health creators closely.", "opportunity_availability": "Applications are open on the brand portal, but the brand states it accepts a limited number of applicants and requires US/Canada residency and age 20+.", "ugc_evidence": "A named ambassador program with unique links, bonuses and paid partnership opportunities built for wellness creators."}'::jsonb);
