  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://loovfood.com/pages/loov-affiliate-program', 'brand_website', 'affiliate_program', 'LOOV''s own affiliate program page, fetched first-hand, publishes 10% commission on referred sales and a 10% audience discount code, sign-up through UpPromote, coupon and loyalty sites routed instead to ShareASale (Merchant ID 143170), monthly payouts via PayPal, a free product once an affiliate reaches $150/month in referred sales, and the contact email partners@loovfood.com. The brand is LOOV Organic OÜ of Tallinn, Estonia, with a US LLC. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
