  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://lovelifesupplements.co.uk/pages/affiliate-programme', 'brand_website', 'affiliate_program', 'Love Life Supplements'' own affiliate programme page, fetched first-hand, publishes 25% commission on a referred customer''s first subscription order and 5% on renewals (up to 12), a 30-day referral window, and payouts via PayPal through the brand''s own affiliate portal. The recorded 25% rate is the first-subscription-order figure, with that basis stated here and in the description. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 21, 9, 16, 7, 8, 4, '{"compensation": "25% on the first subscription order is a strong headline rate, tempered by 5% on renewals and a 30-day window; no cap statement, so the cap is unknown.", "contact_access": "Application runs through the brand''s own programme page and portal; no public partnerships email was published on the fetched page.", "credibility": "An established UK supplement brand with its own storefront and subscription model.", "niche_fit": "Everyday vitamins and wellness supplements fit health, biohacking and daily-routine creators, with a UK audience focus.", "opportunity_availability": "Programme is live and open to apply from the brand page.", "ugc_evidence": "A live brand-run affiliate programme with referral links; creator-specific perks beyond commission are not detailed on the page."}'::jsonb);
