  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/hum-nutrition/', 'affiliate_directory', 'affiliate_program', 'HUM Nutrition''s affiliate program is listed by Lasso at 10% commission per sale with a 30-day cookie, and the 10% rate via ShareASale is corroborated by affiliatemarketinggirl.io and UpPromote. Other figures conflict: Shopper lists 12%, Creator-hero lists 15%, and a separate code-based ambassador channel (humbassador.humnutrition.com) is reported at 20% on net revenue, so the entry is marked publicly_reported at the corroborated 10% network rate with the other channels documented here. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 10, 6, 8, 5, '{"compensation": "10% per sale with a 30-day cookie is corroborated across three directories; conflicting higher figures could not be verified, and no cap statement exists, so the cap is unknown.", "contact_access": "Joining runs through the ShareASale network listing; no public partnerships email was verified.", "credibility": "A major national supplement brand with wide retail distribution, including Sephora.", "niche_fit": "Beauty-from-within supplements for skin, body and mood are a staple fit for beauty, wellness and supplement-routine creators.", "opportunity_availability": "Program is live on ShareASale and joinable now.", "ugc_evidence": "A network affiliate program plus a separate code-based ambassador channel show active creator recruitment, though no brand-run creator page was verified first-hand."}'::jsonb);
