  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://therasagestore.refersion.com/', 'network_profile', 'affiliate_program', 'TheraSage''s program runs on Refersion: its Refersion-hosted Affiliate / Brand Ambassador Agreement (Wellness Products of America, Inc., d/b/a Therasage) guarantees a base commission of ''no less than 5%'' of the price paid on qualifying purchases made with an affiliate''s code, and describes the program as a way to monetize social media user-generated content, requiring an Instagram and a PayPal account. Refersion''s own red-light therapy affiliate roundup lists the Therasage offer at 10% with a $372 average order value and a 30-day cookie, so 10% is recorded as publicly_reported with the 5% contractual floor documented here. The brand''s site publishes the general contact support@therasage.com. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 10, 8, 8, 4, '{"compensation": "Refersion lists the offer at 10% on a $372 average order with a 30-day cookie, while the agreement guarantees only a base of no less than 5%; no cap statement, so the cap is unknown.", "contact_access": "A published brand contact email plus application through the program''s Refersion portal.", "credibility": "A family-founded infrared wellness brand operating for 25+ years and headquartered in Boca Raton, Florida.", "niche_fit": "Portable infrared saunas and red-light devices are visual, routine-based products for wellness, recovery and biohacking creators.", "opportunity_availability": "Program is live on Refersion and open to apply now.", "ugc_evidence": "The program agreement is explicitly built around monetizing social media user-generated content with personal coupon codes."}'::jsonb);
