  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://metamorphosislighttherapy.com/pages/affiliates', 'brand_website', 'affiliate_program', 'Metamorphosis Light Therapy''s own affiliates page, fetched first-hand, publishes a 10% base commission rising to 15% for affiliates generating $5,000 or more per month in sales, a 90-day cookie, free enrollment, and the contact email info@metamorphosislighttherapy.com. The page names no network, so the route is recorded as brand direct. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
