  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Kombucha Kamp Affiliate Program', 'https://www.kombuchakamp.com/affiliate-program', 'https://www.kombuchakamp.com/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.kombuchakamp.com/affiliate-program', 'brand_website', 'affiliate_program', 'Kombucha Kamp''s own affiliate program page, fetched first-hand, confirms a live program with tracked referral links, a 30-day cookie window, bonuses and commissions described as paid immediately, plus a free copy of The Kombucha Handbook for affiliates. However, the page''s figures conflict: its header promises ''Earn 10%–50% commission on every sale (varies by offer)'' while its Easy Commission Structure section states ''8% Commission on All Sales'' with a higher commission for virtual products. Because the brand''s own page conflicts, commission_rate is null with the conflict documented here. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 10, 6, 6, 9, 4, '{"compensation": "The program is confirmed on the brand''s own page, but its published figures conflict (10%\u201350% in the header vs 8% on all sales in the structure section), so no rate is recorded.", "contact_access": "Application runs from the brand''s own affiliate page; no public partnerships email was published on the fetched page.", "credibility": "A 20+ year category educator and the best-known name in home kombucha brewing.", "niche_fit": "Home kombucha brewing cultures and kits fit fermentation, gut-health and DIY food creators, though the niche is narrower than mainstream food and drink.", "opportunity_availability": "Program is live with free, near-instant application from the brand page.", "ugc_evidence": "A brand-run program aimed at wellness advocates and fermentation enthusiasts, with giveaway and content partnership opportunities."}'::jsonb);
