  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/91571', 'network_profile', 'affiliate_program', 'Codeage''s official Awin merchant profile (91571), fetched first-hand, confirms a live affiliate program and describes Codeage as ''a leading e-commerce business and fast-growing nutrition startup based in Los Angeles'' selling nutritional supplements across the US, Canada, Australia and the UK; the brand''s own help center likewise confirms an affiliate program for partners with a blog, newsletter or audience and publishes the contact support@codeage.com. The Awin profile publishes no commission percentage, and the only third-party figure (Shopper''s ''up to 10.5%'') is a ceiling from a single directory, so commission_rate is null. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 10, 8, 8, 9, 4, '{"compensation": "A commission-paying program is confirmed on the Awin profile and the brand''s help center, but no rate is published, so no rate is recorded.", "contact_access": "A published brand contact email (support@codeage.com) plus joining through the Awin merchant profile.", "credibility": "A fast-growing, Los Angeles-based nutrition brand selling across the US, Canada, Australia and the UK per its Awin profile.", "niche_fit": "A broad supplement line (multivitamins, collagen, probiotics) fits health, wellness and longevity creators closely.", "opportunity_availability": "Program is live on Awin and joinable now.", "ugc_evidence": "An open network program on Awin aimed at blogs, newsletters and audiences; creator-specific recruitment beyond the listing was not verified."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('SONOFF', 'https://sonoff.tech', 'Smart home brand (ITEAD) selling Wi-Fi and Zigbee smart switches, relays, sensors, plugs and lighting sold through sonoff.tech. Its own affiliate program page — explicitly aimed at bloggers, influencers, publishers and content creators — publishes 10%-15% commission, a 30-day cookie, monthly PayPal payouts and a dedicated dashboard, run through GoAffPro.', 'China', 'published') returning id into bid;
