  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'SONOFF Affiliate Program — brand''s own page publishes 10%-15% commission (recorded at the 10% floor), 30-day cookie, monthly PayPal payouts, explicitly open to creators and influencers', 'https://sonoff.tech/en-eu/pages/affiliate', 'https://sonoff.tech/en-eu/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://sonoff.tech/en-eu/pages/affiliate', 'official_site', 'affiliate', 'SONOFF''s own affiliate program page fetched in full: ''earn up to 15% commission for every referral'', ''Enjoy 10%-15% commissions and a 30-day cookie window'', monthly payouts via PayPal after a 30-day hold, free to join, applications confirmed within 1-2 business days, sign-up routed to its GoAffPro portal (sonoff-affiliate.goaffpro.com). The FAQ states the program ''is designed for bloggers, influencers, publishers, and content creators'' and supports ''content-based partnerships, such as blogs, creators, influencers, and review-driven media''; influencers can also apply for free review products. The recorded 10% is the floor of the brand-published range. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 17, 15, 9, 9, 4, '{"compensation": "10%-15% published by the brand is strong for smart home hardware; the recorded floor is 10% and no cap statement is published", "contact_access": "Direct application from the brand''s own program page into its GoAffPro portal; no affiliate email is published", "credibility": "A leading smart home brand with millions of users worldwide, sold globally through its own store", "niche_fit": "Smart switches, relays and sensors are core smart-home UGC \u2014 install walkthroughs, automations and room tours are natural creator content", "opportunity_availability": "Open application, free to join, decisions within 1-2 business days; program live since August 2025", "ugc_evidence": "The brand''s own program page names bloggers, influencers and content creators as its audience, supports content-based partnerships, and offers influencers free products to review"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Qsee', 'https://www.q-see.com', 'US-based security camera and surveillance brand with over 20 years in the field, selling home and office camera systems through q-see.com. Its own affiliate program page publishes 10%-15% commissions via UpPromote, a 30-day cookie, payments processed in 1-3 business days, product trials for affiliates and a named business-development contact.', 'United States', 'published') returning id into bid;
