  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.q-see.com/pages/affiliate-program', 'official_site', 'affiliate', 'Qsee''s own affiliate program page fetched in full: ''Earn 10% to 15% commissions on sales volume'', a sales tracking cookie active for up to 30 days, average order of $250 (''you will get paid on average $25 per order''), commissions processed in 1-3 business days via PayPal, Zelle or bank transfer, free product trials and cash bonuses for affiliates, and ''Qsee has partnered with Uppromote'' for sign-up. The page publishes a direct contact: ''contact our business development manager at sales@q-see.com''. The recorded 10% is the floor of the brand-published range. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 15, 12, 8, 4, '{"compensation": "10%-15% on a ~$250 average order is strong for surveillance hardware, with unusually fast 1-3 business day payouts; no cap statement is published", "contact_access": "The program page publishes a named business-development manager email (sales@q-see.com) alongside the application route", "credibility": "US-based company with over 20 years in surveillance, its own factory and a US warehouse", "niche_fit": "Home security cameras are proven UGC territory \u2014 install videos, footage tests and smart-home security setups", "opportunity_availability": "Open application through the brand''s own page and UpPromote, subject to approval", "ugc_evidence": "A brand-published affiliate program on the brand''s own page with product trials for affiliates; aimed at referral partners generally rather than a named creator tier"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Rigid.PRO', 'https://rigid.pro', 'Two-person Australian workshop hand-building cinema rigs (the OMNIA and CineRig) that turn compact mirrorless cameras like the Sony FX3 and Canon R5C into cineback-style rigs, sold from $249 USD through rigid.pro. Its creator/affiliate page promises ''Affiliate income with no ceiling'' — every rig sold through a creator''s referral link pays commission for the lifetime of the content — with a creator discount code (BESTRIG) and brand promotion of creator videos.', 'Australia', 'published') returning id into bid;
