  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://rigid.pro/pages/collabs.', 'https://rigid.pro/pages/collabs', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Rigid.PRO Creator & Affiliate Program — brand''s own page states ''Affiliate income with no ceiling'' (UNCAPPED); commission rate unpublished, rigs from $249, creators buy at a discount and earn for the lifetime of their content', 'https://rigid.pro/pages/collabs', 'https://rigid.pro/pages/collabs', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://rigid.pro/pages/collabs', 'official_site', 'affiliate', 'Rigid.PRO''s own ''Work With Rigid.PRO | Creator & Affiliate Program'' page fetched in full. It states verbatim: ''Affiliate income with no ceiling — Every rig sold through your referral link earns you a commission. Not once — for the lifetime of your content.'' That explicit no-ceiling statement on affiliate earnings is why the cap is recorded as UNCAPPED. The model: join the affiliate program, buy a rig with the creator discount code BESTRIG, make review/build content, and earn on every sale ''forever''; the brand actively features creator content and says its Reviews page has generated 200,000+ views for featured filmmakers. No commission percentage is published anywhere on the page, so the rate is honestly null. The brand is a husband-and-wife team hand-building rigs in Australia and states it takes 10+ collab requests a day — a demand figure, not a creator count — so saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 18, 12, 8, 7, 3, '{"compensation": "Earnings are explicitly uncapped and pay for the lifetime of a video, but the commission percentage itself is not published, which caps this score", "contact_access": "Sign-up is through the brand''s own collabs page; no affiliate email is published", "credibility": "A very small two-person workshop operation; a genuine niche reputation among filmmakers, but far less established than the global brands in this round", "niche_fit": "Cinema rigs for mirrorless cameras are pure filmmaker gear \u2014 rig builds, reviews and behind-the-scenes content are exactly what camera creators make", "opportunity_availability": "Open to join, but the model expects creators to purchase a rig first (from $249 with the creator code), so it is not a zero-cost start", "ugc_evidence": "A creator program designed around creators buying, honestly reviewing and being featured by the brand; it explicitly refuses paid or scripted reviews"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Aquasana', 'https://www.aquasana.com', 'Austin, Texas water-filtration brand (an A. O. Smith company) selling whole-house, under-sink, countertop and shower filters through aquasana.com. Its affiliate program runs through Rakuten Advertising at a reported 10% commission, and the brand''s own affiliate starter kit publishes a dedicated affiliate team contact, affiliates@aquasana.com.', 'United States', 'published') returning id into bid;
