  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://cdn.aquasana.com/assets/PressKit/Presskit_Affiliate_2018.pdf', 'official_site', 'contact', 'Aquasana''s own Affiliate Starter Kit, hosted on the brand''s CDN and fetched in full, closes with: ''CONTACT — Aquasana Affiliate Team — affiliates@aquasana.com — For more information, visit us at: aquasana.com/affiliates''. The same document confirms the brand is based in Austin, Texas and was acquired in 2016 by A. O. Smith Corporation.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://3hundrd.com/water-filtration-affiliate-programs', 'directory', 'affiliate', 'A water-filtration affiliate roundup reports Aquasana''s program ''running through Rakuten Marketing that allows affiliates to earn a clean 10% commission per sale'', with a chance to earn double commission on selected products; an independent publisher affiliate disclosure likewise lists ''Aquasana via Rakuten Advertising (LinkShare)'', managed by PartnerCentric. The 10% rate and Rakuten route are therefore recorded as publicly reported rather than brand-published. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation stays unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 13, 13, 12, 8, 5, '{"compensation": "A reported 10% on systems that run to several hundred dollars is solid; the rate is directory-reported rather than brand-published, and no cap statement exists", "contact_access": "The brand''s own affiliate starter kit publishes a dedicated affiliate team email (affiliates@aquasana.com) plus an affiliates page", "credibility": "An established filtration brand owned by A. O. Smith, with NSF-certified products and national retail presence", "niche_fit": "Water filtration is strong home-health UGC \u2014 install videos, taste tests and water-quality content for whole-house and under-sink systems", "opportunity_availability": "Application through Rakuten Advertising, subject to network and brand approval", "ugc_evidence": "A long-running affiliate program with a dedicated affiliate team and starter kit published by the brand; no named creator tier"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Nextbase', 'https://www.nextbase.com', 'UK dash cam brand — the most awarded in the category, with 125+ patents — selling dash cams, rear camera modules and accessories through nextbase.com at around a $200 average order value. Its own US ''Become an Affiliate'' page publishes a 5% base commission rate, a 14-day cookie and seeding/contest opportunities; the program runs via Awin (its UK page publishes 8% with a 30-day cookie).', 'United Kingdom', 'published') returning id into bid;
