  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://nextbase.com/become-an-affiliate/.', 'https://nextbase.com/become-an-affiliate/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Nextbase Affiliate Program — brand''s own US page publishes 5% base commission via Awin, 14-day cookie, ~$200 AOV, seeding and contest opportunities', 'https://nextbase.com/become-an-affiliate/', 'https://nextbase.com/become-an-affiliate/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://nextbase.com/become-an-affiliate/', 'official_site', 'affiliate', 'Nextbase''s own US ''Become an Affiliate'' page fetched in full: ''5% base commission rate, with the chance to earn more'', ''Opportunities for seeding and contests'', ''14-day cookie period'', and ''an average order value of around $200 and a solid 10% conversion rate''. A directory profile (LinkClicky) names Awin as the US affiliate platform with the same 14-day cookie, which is the network recorded. The brand''s UK page publishes different regional terms (8% commission, 30-day cookie) — the recorded 5% is the US program''s brand-published base rate. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 10, 9, 8, 5, '{"compensation": "5% base is modest, though on a ~$200 average order with a brand-claimed 10% conversion rate; the UK program''s 8% shows headroom by region", "contact_access": "Application from the brand''s own affiliate page into Awin; no affiliate email is published", "credibility": "The global dash cam market leader \u2014 the most awarded brand in the category with 125+ patents", "niche_fit": "Dash cams generate natural UGC \u2014 road footage, install guides and safety stories \u2014 and Nextbase actively features customer dash cam videos", "opportunity_availability": "Open application through Awin, subject to approval", "ugc_evidence": "A brand-published affiliate page with product seeding and contests for affiliates, plus a standing brand channel for featuring creator footage"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('FurHaven', 'https://furhaven.com', 'Pet products brand founded in 2004, best known for orthopedic, sofa-style and calming dog and cat beds (600+ styles, sizes, fabrics and colors), sold through furhaven.com. Its affiliate program is consistently reported at 10% commission with a 30-day cookie and a ~$75 average order value, managed through ShareASale (with Awin also reported).', 'United States', 'published') returning id into bid;
