  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'FurHaven Affiliate Program — reported 10% commission via ShareASale, 30-day cookie, ~$75 average order value on pet beds', 'https://getlasso.co/affiliate/furhaven-pet-products/', 'https://getlasso.co/affiliate/furhaven-pet-products/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/furhaven-pet-products/', 'directory', 'affiliate', 'Multiple independent affiliate roundups agree on FurHaven''s terms: 10% commission per sale and a 30-day cookie (Lasso, PrettyLinks, Admitad and AffMaven all report 10% / 30 days; PrettyLinks adds a $75 average order value and 9.2% conversion rate). Digiexe names ShareASale as the managing network and AdCompares confirms the rate is ''available through both ShareASale and Awin'' — ShareASale is the network recorded. The brand''s own homepage (fetched) confirms the pet-bed catalogue the program covers. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation stays unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 13, 8, 8, 4, '{"compensation": "10% flat with a 30-day cookie is fair for the category, though the ~$75 average order keeps per-sale earnings modest; no cap statement is published", "contact_access": "Application runs through the ShareASale network listing; no affiliate email is published", "credibility": "Founded in 2004 and sold nationally; an established mid-size pet brand", "niche_fit": "Pet beds are a staple of pet UGC \u2014 unboxings, senior-dog comfort stories and home tours \u2014 across a 600+ style catalogue", "opportunity_availability": "Open network application, subject to approval", "ugc_evidence": "The program is reported across roundups as aimed at pet bloggers and influencers; no dedicated creator tier was verified on a brand page"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Big Barker', 'https://www.bigbarker.com', 'Orthopedic dog bed brand (Barker Beds) built for large and giant breeds and senior dogs, with 7-inch foam beds at $200-$400+ price points, vet recommendations and a 10-year warranty, sold through bigbarker.com. Its affiliate program runs direct through Refersion under its parent entity Barker Wellness at a reported 10% of net revenue.', 'United States', 'published') returning id into bid;
