  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Big Barker Affiliate Program — reported 10% of net revenue (basis: net revenue, not sale price) via Refersion, on $200-$400+ orthopedic dog beds', 'https://adcompares.com/affiliate/programs/dog/', 'https://adcompares.com/affiliate/programs/dog/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://adcompares.com/affiliate/programs/dog/', 'directory', 'affiliate', 'A detailed dog-bed affiliate roundup reports Big Barker''s program ''runs under its parent entity, Barker Wellness, through Refersion'', with a ''Commission Rate: 10% of net revenue'', a ''clear, single-tier commission structure (10% flat on net revenue)'' and an ''Average Order Value: $200-$400+''. IMPORTANT BASIS NOTE: the 10% is calculated on NET REVENUE, not on the headline sale price, and it is recorded on that basis. The brand''s own homepage (fetched) confirms the positioning behind the numbers: beds from $249.95, ''Vet Recommended'', and a 10-year warranty. Cookie duration is not publicly disclosed by the Refersion listing. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation stays unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 14, 8, 8, 4, '{"compensation": "10% of net revenue on $200-$400+ orders works out to roughly $20-$40 per sale \u2014 strong for pet products \u2014 but the net-revenue basis and undisclosed cookie temper it", "contact_access": "Application runs through the brand''s Refersion program; no affiliate email is published", "credibility": "An established niche brand with vet recommendations and a 10-year warranty on its beds", "niche_fit": "Orthopedic beds for big and senior dogs are a focused, emotional UGC niche \u2014 joint-health stories, vet content and large-breed reviews", "opportunity_availability": "Open direct application, subject to approval", "ugc_evidence": "A direct Refersion program reported as suited to large-breed blogs and orthopedic product reviews; no named creator tier was verified"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Rowenta', 'https://www.rowentausa.com', 'Premium home appliance brand with over 100 years of history (Groupe SEB), known for steam stations, irons and garment care, sold in the US through rowentausa.com. Its own affiliate program page routes applications through CJ Affiliate with dedicated support and creative assets, and publishes a direct affiliate team contact — but no commission rate is published on the page, so the rate is honestly null.', 'Germany', 'published') returning id into bid;
