  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.rowentausa.com/rowenta-affiliate-program', 'official_site', 'affiliate', 'Rowenta USA''s own affiliate program page fetched in full: ''Through our partnership with CJ Affiliate, we offer competitive commissions, proven conversion rates, and dedicated support'', sign-up is ''through Commission Junction''s secure platform'', affiliates get creative assets, links and product feeds, and the page publishes ''Contact our affiliate team: affiliates@rowentausa.com''. The page publishes NO commission percentage — rates live inside CJ — so the rate is honestly null rather than guessed. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 8, 12, 8, 5, '{"compensation": "No rate is published on the brand''s page \u2014 terms sit inside CJ \u2014 so compensation can only be scored on the program''s existence, not its generosity", "contact_access": "The program page publishes a direct affiliate team email (affiliates@rowentausa.com) alongside the CJ application route", "credibility": "A global brand with over 100 years of trust, part of Groupe SEB", "niche_fit": "Premium steam irons and garment care fit home, laundry and lifestyle UGC, though the content angle is narrower than smart home or pet", "opportunity_availability": "Open application through CJ Affiliate, subject to approval", "ugc_evidence": "A brand-published program page aimed at lifestyle, home and appliance publishers with dedicated support; no named creator tier"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Medify Air', 'https://medifyair.com', 'Boca Raton, Florida air purifier brand selling HEPA purifiers (MA-14 through the MA-112 PRO, $89-$595) through medifyair.com. Its affiliate program is reported as Refersion-tracked with a personalized ambassador code and a dedicated affiliate management team — but published rates conflict (10% in one detailed roundup, 5% at Shopper), so the rate is honestly null with the conflict documented.', 'United States', 'published') returning id into bid;
