  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Refersion', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://commission.academy/blog/best-air-purifier-affiliate-programs/.', 'https://commission.academy/blog/best-air-purifier-affiliate-programs/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Medify Air Affiliate Program — reported Refersion program with ambassador codes (rate conflicted: 10% vs 5% across sources, recorded as null); contact partnerships@medifyair.com', 'https://commission.academy/blog/best-air-purifier-affiliate-programs/', 'https://commission.academy/blog/best-air-purifier-affiliate-programs/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://commission.academy/blog/best-air-purifier-affiliate-programs/', 'directory', 'affiliate', 'An air-purifier affiliate roundup reports Medify Air''s program as: ''10% sales commission'', ''30 days referral window'', ''Personalised Ambassador Code'', ''Dedicated affiliate management team'', ''Integrated with Refersion tracking software'' and ''monthly payouts via PayPal''. CONFLICT: Shopper''s partnership listing reports a 5% payout for the same program. Because the two published figures conflict and no brand page settles them, the commission rate is recorded as null with this conflict documented, and Refersion is the network recorded (the only network named by any source). The brand''s own homepage (fetched) confirms the Boca Raton, Florida base and publishes a media/partnerships email, partnerships@medifyair.com. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation stays unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 8, 10, 8, 3, '{"compensation": "Published rates conflict (10% vs 5%) and no brand page settles them, so the rate is null and compensation scores low until verified", "contact_access": "The brand''s own site publishes a partnerships email (partnerships@medifyair.com); the affiliate application itself runs through Refersion reporting", "credibility": "An established US purifier brand, but its program terms are only thinly and inconsistently reported, which docks credibility for this listing", "niche_fit": "Air purifiers are steady home-health UGC \u2014 allergy, smoke and pet-dander content across an $89-$595 range", "opportunity_availability": "Open application reported through Refersion, subject to approval", "ugc_evidence": "Reporting describes ambassador codes and a dedicated affiliate management team, suggesting a worked-with-creators program, though no brand program page was fetched"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Coway', 'https://www.cowaymega.com', 'South Korean home-wellness appliance brand best known for the design-led Airmega air purifiers, plus water purifiers and bidets, sold in the US through cowaymega.com. Its affiliate program runs through Impact at a reported 1.5%-3% commission with a 7-day cookie — the recorded rate is the 1.5% floor of the reported range.', 'South Korea', 'published') returning id into bid;
