  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Coway Affiliate Program — reported 1.5%-3% commission (recorded at the 1.5% floor) via Impact, 7-day cookie, on Airmega air purifiers', 'https://linkclicky.com/affiliate-program/coway/', 'https://linkclicky.com/affiliate-program/coway/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/coway/', 'directory', 'affiliate', 'A directory profile of Coway''s program lists: Website cowaymega.com, ''Affiliate Platform: Impact'', ''Commission: 1.5%-3% per sale''; Lasso''s profile independently reports 3% per sale with a 7-day cookie, consistent with the top of that range. The recorded 1.5% is the floor of the reported range and Impact is the network recorded. Note for transparency: Coway also sells through a direct-sales ''Health Planner'' channel in some markets — that is a separate salesforce model, not this listing; the recorded program is the standard Impact network affiliate program. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation stays unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 11, 6, 8, 8, 3, '{"compensation": "1.5%-3% with a short 7-day cookie is the weakest pay structure in this round, even on premium-priced purifiers", "contact_access": "Application runs through the Impact network listing; no affiliate email is published", "credibility": "A major global appliance brand, docked because it also operates a direct-sales ''Health Planner'' channel in some markets and its affiliate terms are only directory-reported", "niche_fit": "Design-led Airmega purifiers photograph well and fit home-wellness and clean-air UGC", "opportunity_availability": "Open application through Impact, subject to approval", "ugc_evidence": "A standard network affiliate program on Impact; no creator-specific tier or seeding offer was reported"}'::jsonb);
